public class Main {
    // 分割字符串
    static LinkedList<Pair> splitStr(String s) {
        LinkedList<Pair> res = new LinkedList<>();
        StringBuilder num = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                num.append(c);
            } else {
                res.add(new Pair(c, Integer.parseInt(num.toString())));
                num.setLength(0);
            }
        }
        return res;
    }
​
    static class Pair {
        char ch;
        int count;
        Pair(char ch, int count) {
            this.ch = ch;
            this.count = count;
        }
    }
​
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s1 = sc.nextLine();
        String s2 = sc.nextLine();
​
        LinkedList<Pair> list1 = splitStr(s1);
        LinkedList<Pair> list2 = splitStr(s2);
​
        int diff = 0;
        int same = 0;
        // 循环对比
        while (!list1.isEmpty()) {
            Pair p1 = list1.pollFirst();
            Pair p2 = list2.pollFirst();
            int compareNum = Math.min(p1.count, p2.count);
​
            if (p1.ch == p2.ch) {
                same += compareNum;
            } else {
                diff += compareNum;
            }
​
            if (p1.count > compareNum) {
                list1.addFirst(new Pair(p1.ch, p1.count - compareNum));
            }
            if (p2.count > compareNum) {
                list2.addFirst(new Pair(p2.ch, p2.count - compareNum));
            }
        }
​
        System.out.println(diff + "/" + (diff + same));
    }
}
