const readline = require('readline');
​
function parseString(s) {
    let res = [];
    let num = '';
    for (let c of s) {
        if (/\d/.test(c)) {
            num += c;
        } else {
            res.push([c, parseInt(num)]);
            num = '';
        }
    }
    return res;
}
​
const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
const lines = [];
​
rl.on('line', line => {
    lines.push(line);
    if (lines.length === 2) {
        const list1 = parseString(lines[0]);
        const list2 = parseString(lines[1]);
​
        let i = 0, j = 0;
        let cnt1 = list1[0][1], cnt2 = list2[0][1];
        let ch1 = list1[0][0], ch2 = list2[0][0];
        let same = 0, diff = 0;
        // 双指针
        while (i < list1.length && j < list2.length) {
            const compareNum = Math.min(cnt1, cnt2);
​
            if (ch1 === ch2) same += compareNum;
            else diff += compareNum;
​
            cnt1 -= compareNum;
            cnt2 -= compareNum;
​
            if (cnt1 === 0) {
                i++;
                if (i < list1.length) {
                    ch1 = list1[i][0];
                    cnt1 = list1[i][1];
                }
            }
            if (cnt2 === 0) {
                j++;
                if (j < list2.length) {
                    ch2 = list2[j][0];
                    cnt2 = list2[j][1];
                }
            }
        }
​
        console.log(`${diff}/${diff + same}`);
        rl.close();
    }
});
