package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "unicode"
)
​
// 解析压缩字符串，返回 [字符, 次数] 的切片
func parse(s string) [][2]interface{} {
    var res [][2]interface{}
    num := ""
    for _, c := range s {
        if unicode.IsDigit(c) {
            num += string(c)
        } else {
            n, _ := strconv.Atoi(num)
            res = append(res, [2]interface{}{c, n})
            num = ""
        }
    }
    return res
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    s1, _ := reader.ReadString('\n')
    s2, _ := reader.ReadString('\n')
​
    s1 = s1[:len(s1)-1]
    s2 = s2[:len(s2)-1]
​
    list1 := parse(s1)
    list2 := parse(s2)
​
    i, j := 0, 0
    cnt1 := list1[0][1].(int)
    cnt2 := list2[0][1].(int)
    ch1 := list1[0][0].(rune)
    ch2 := list2[0][0].(rune)
    same, diff := 0, 0
​
    for i < len(list1) && j < len(list2) {
        compare := min(cnt1, cnt2)
        if ch1 == ch2 {
            same += compare
        } else {
            diff += compare
        }
        cnt1 -= compare
        cnt2 -= compare
​
        if cnt1 == 0 {
            i++
            if i < len(list1) {
                ch1 = list1[i][0].(rune)
                cnt1 = list1[i][1].(int)
            }
        }
        if cnt2 == 0 {
            j++
            if j < len(list2) {
                ch2 = list2[j][0].(rune)
                cnt2 = list2[j][1].(int)
            }
        }
    }
​
    fmt.Printf("%d/%d\n", diff, diff+same)
}
​
func min(a, b int) int {
    if a < b {
        return a
    }
    return b
}
